// Book category drives loan duration and fine rate.
enum BookCategory {
    REGULAR, // standard circulation title
    PREMIUM  // new release, shorter loan, higher fine
}

// Lifecycle status of a single physical copy.
enum CopyStatus {
    AVAILABLE,    // free to be checked out
    CHECKED_OUT   // currently with a member
}

// A catalog title, which may have several physical copies.
class Book {
    private final String bookId;         // unique id, e.g. B1
    private final String title;          // display title
    private final BookCategory category; // policy tier

    public Book(String bookId, String title, BookCategory category) {
        this.bookId = bookId;     // store id
        this.title = title;        // store title
        this.category = category;  // store category
    }

    public String getBookId() { return bookId; }         // id getter
    public String getTitle() { return title; }             // title getter
    public BookCategory getCategory() { return category; } // category getter
}

// One physical copy of a book.
class BookCopy {
    private final String copyId; // unique id, e.g. B1-C1
    private final String bookId; // which title this copy belongs to
    private CopyStatus status;   // current lifecycle state

    public BookCopy(String copyId, String bookId) {
        this.copyId = copyId;  // store id
        this.bookId = bookId;   // store title reference
        this.status = CopyStatus.AVAILABLE; // new copies start free
    }

    public String getCopyId() { return copyId; }       // id getter
    public String getBookId() { return bookId; }         // book getter
    public CopyStatus getStatus() { return status; }     // status getter
    public void setStatus(CopyStatus status) { this.status = status; } // status setter
    public boolean isAvailable() { return status == CopyStatus.AVAILABLE; } // convenience check
}

// Creates copies with title-prefixed ids for a book.
class BookCopyFactory {
    public java.util.List<BookCopy> createCopies(String bookId, int count) {
        java.util.List<BookCopy> created = new java.util.ArrayList<>(); // result list
        for (int i = 1; i <= count; i++) {                                // create 'count' copies
            created.add(new BookCopy(bookId + "-C" + i, bookId));          // e.g. B1-C1
        }
        return created; // hand back the new copies
    }
}

