// Strategy interface: eligibility, loan duration, and fine policy.
interface BorrowingEligibilityStrategy {
    // Returns null if eligible, or a rejection reason string if not.
    String checkEligibility(Member member, int activeLoanCount);
    int loanDurationDays(BookCategory category);          // how many days a loan of this category runs
    double fineForDaysLate(BookCategory category, int daysLate); // fine owed for this many late days
}

// Caps active loans at 3, outstanding fines at 5.0, and applies per-category loan terms.
class LimitAndFineEligibilityStrategy implements BorrowingEligibilityStrategy {
    private static final int MAX_ACTIVE_LOANS = 3;      // loan-count ceiling
    private static final double MAX_OUTSTANDING_FINE = 5.0; // fine-balance ceiling

    @Override
    public String checkEligibility(Member member, int activeLoanCount) {
        if (member.getOutstandingFines() > MAX_OUTSTANDING_FINE) { // fine balance too high
            return "Outstanding fines exceed limit";
        }
        if (activeLoanCount >= MAX_ACTIVE_LOANS) {                  // already at the loan cap
            return "Loan limit reached";
        }
        return null; // eligible: fines are within limit and loan count has room
    }

    @Override
    public int loanDurationDays(BookCategory category) {
        return category == BookCategory.PREMIUM ? 7 : 14; // premium loans are shorter
    }

    @Override
    public double fineForDaysLate(BookCategory category, int daysLate) {
        if (daysLate <= 0) return 0.0;                                // not late, no fine
        double perDay = category == BookCategory.PREMIUM ? 1.0 : 0.5;  // fine rate per category
        double cap = category == BookCategory.PREMIUM ? 10.0 : 5.0;    // maximum fine per loan
        double raw = perDay * daysLate;                                  // uncapped fine
        return Math.min(raw, cap);                                        // clamp to the cap
    }
}

// A library member and their outstanding fine balance.
class Member {
    private final String memberId;  // unique id
    private final String name;      // display name
    private double outstandingFines; // unpaid fine balance

    public Member(String memberId, String name, double outstandingFines) {
        this.memberId = memberId;             // store id
        this.name = name;                      // store name
        this.outstandingFines = outstandingFines; // store starting fine balance
    }

    public String getMemberId() { return memberId; }               // id getter
    public String getName() { return name; }                        // name getter
    public double getOutstandingFines() { return outstandingFines; } // fine getter
    public void addFine(double amount) { outstandingFines += amount; } // accrue a new fine
}

// A single loan of one copy to one member.
class Loan {
    private final String loanId;    // unique id
    private final String memberId;  // who borrowed it
    private final String copyId;    // which physical copy
    private final String bookId;    // which title
    private final int checkoutDay;  // day the loan started
    private final int dueDay;       // day it is due back
    private double fine;             // fine charged on return, 0 until returned
    private String status;           // ACTIVE, RETURNED

    public Loan(String loanId, String memberId, String copyId, String bookId, int checkoutDay, int dueDay) {
        this.loanId = loanId;         // store id
        this.memberId = memberId;      // store member
        this.copyId = copyId;          // store copy
        this.bookId = bookId;          // store title
        this.checkoutDay = checkoutDay; // store checkout day
        this.dueDay = dueDay;           // store due day
        this.fine = 0.0;                 // no fine yet
        this.status = "ACTIVE";          // starts active
    }

    public String getLoanId() { return loanId; }         // id getter
    public String getMemberId() { return memberId; }      // member getter
    public String getCopyId() { return copyId; }          // copy getter
    public String getBookId() { return bookId; }          // book getter
    public int getDueDay() { return dueDay; }              // due day getter
    public double getFine() { return fine; }               // fine getter
    public void setFine(double fine) { this.fine = fine; } // fine setter
    public String getStatus() { return status; }           // status getter
    public void setStatus(String status) { this.status = status; } // status setter
}

