#include <string>
#include <algorithm>
using namespace std;

// Strategy interface: eligibility, loan duration, and fine policy.
class BorrowingEligibilityStrategy {
public:
    // Returns empty string if eligible, or a rejection reason string if not.
    virtual string checkEligibility(const Member& member, int activeLoanCount) = 0;
    virtual int loanDurationDays(BookCategory category) = 0;             // how many days a loan of this category runs
    virtual double fineForDaysLate(BookCategory category, int daysLate) = 0; // fine owed for this many late days
    virtual ~BorrowingEligibilityStrategy() {}
};

// Caps active loans at 3, outstanding fines at 5.0, and applies per-category loan terms.
class LimitAndFineEligibilityStrategy : public BorrowingEligibilityStrategy {
    const int maxActiveLoans = 3;          // loan-count ceiling
    const double maxOutstandingFine = 5.0;  // fine-balance ceiling

public:
    string checkEligibility(const Member& member, int activeLoanCount) override {
        if (member.outstandingFines > maxOutstandingFine) { // fine balance too high
            return "Outstanding fines exceed limit";
        }
        if (activeLoanCount >= maxActiveLoans) {               // already at the loan cap
            return "Loan limit reached";
        }
        return ""; // eligible: fines are within limit and loan count has room
    }

    int loanDurationDays(BookCategory category) override {
        return (category == BookCategory::PREMIUM) ? 7 : 14; // premium loans are shorter
    }

    double fineForDaysLate(BookCategory category, int daysLate) override {
        if (daysLate <= 0) return 0.0;                                  // not late, no fine
        double perDay = (category == BookCategory::PREMIUM) ? 1.0 : 0.5;  // fine rate per category
        double cap = (category == BookCategory::PREMIUM) ? 10.0 : 5.0;    // maximum fine per loan
        double raw = perDay * daysLate;                                     // uncapped fine
        return min(raw, cap);                                                 // clamp to the cap
    }
};

// A library member and their outstanding fine balance.
class Member {
public:
    string memberId;         // unique id
    string name;               // display name
    double outstandingFines;   // unpaid fine balance

