// Observer interface: reacts to library lifecycle events.
interface LibraryObserver {
    void onLoanCreated(Loan loan);                         // copy assigned
    void onLoanRejected(String memberId, String reason);    // ineligible
    void onHoldPlaced(String memberId, String bookId);      // no copy, joined hold queue
    void onLoanReturned(Loan loan, double fine);            // copy returned, fine computed
}

// Simple observer that prints events to the console.
class ConsoleLibraryObserver implements LibraryObserver {
    @Override
    public void onLoanCreated(Loan loan) {
        System.out.println("Loan " + loan.getLoanId() + " created for " + loan.getMemberId() + ", copy " + loan.getCopyId() + ", due day " + loan.getDueDay());
    }

    @Override
    public void onLoanRejected(String memberId, String reason) {
        System.out.println("Checkout rejected for " + memberId + ": " + reason);
    }

    @Override
    public void onHoldPlaced(String memberId, String bookId) {
        System.out.println("Hold placed for " + memberId + " on book " + bookId);
    }

    @Override
    public void onLoanReturned(Loan loan, double fine) {
        System.out.println("Loan " + loan.getLoanId() + " returned by " + loan.getMemberId() + ", fine " + fine);
    }
}

// Custom exceptions for the realistic failure modes.
class BorrowingNotEligibleException extends RuntimeException {
    public BorrowingNotEligibleException(String msg) { super(msg); }
}
class InvalidLoanException extends RuntimeException {
    public InvalidLoanException(String msg) { super(msg); }
}
class LoanNotActiveException extends RuntimeException {
    public LoanNotActiveException(String msg) { super(msg); }
}

// The core orchestrator tying every piece together.
class LibraryService {
    private final java.util.Map<String, Book> books = new java.util.HashMap<>();          // bookId -> Book
    private final java.util.Map<String, BookCopy> copies = new java.util.HashMap<>();      // copyId -> BookCopy
    private final java.util.Map<String, Member> members = new java.util.HashMap<>();       // memberId -> Member
    private final java.util.Map<String, Loan> loans = new java.util.HashMap<>();           // loanId -> Loan
    private final java.util.Map<String, java.util.List<String>> holds = new java.util.HashMap<>(); // bookId -> FIFO queue of memberIds
    private final BorrowingEligibilityStrategy eligibilityStrategy; // pluggable policy
    private final java.util.List<LibraryObserver> observers = new java.util.ArrayList<>(); // listeners
    private int loanCounter = 0; // simple id generator

    public LibraryService(BorrowingEligibilityStrategy eligibilityStrategy) {
        this.eligibilityStrategy = eligibilityStrategy; // store chosen policy
    }

    public void addBook(Book book) { books.put(book.getBookId(), book); holds.put(book.getBookId(), new java.util.ArrayList<>()); } // register a book and its hold queue
    public void addCopies(java.util.List<BookCopy> newCopies) { for (BookCopy c : newCopies) copies.put(c.getCopyId(), c); } // register copies
    public void addMember(Member member) { members.put(member.getMemberId(), member); } // register a member
    public void addObserver(LibraryObserver observer) { observers.add(observer); }          // register a listener

    private int activeLoanCount(String memberId) {
        int count = 0;                                                // running total
        for (Loan l : loans.values()) {                                 // scan all loans
            if (l.getMemberId().equals(memberId) && "ACTIVE".equals(l.getStatus())) count++; // count active ones
        }
        return count; // total active loans for this member
    }

    private BookCopy findFreeCopy(String bookId) {
        for (BookCopy c : copies.values()) {                             // scan all copies
            if (c.getBookId().equals(bookId) && c.isAvailable()) return c; // first free copy of this title
        }
        return null; // no free copy
    }

    // Checks out a copy if eligible and available, else waitlists, else throws.
    public synchronized Loan checkout(String memberId, String bookId) {
        Member member = members.get(memberId);                          // look up member
        Book book = books.get(bookId);                                    // look up book
        String reason = eligibilityStrategy.checkEligibility(member, activeLoanCount(memberId)); // eligibility check
        if (reason != null) {                                              // not eligible
            for (LibraryObserver obs : observers) obs.onLoanRejected(memberId, reason); // notify
            throw new BorrowingNotEligibleException(reason);
        }
        BookCopy copy = findFreeCopy(bookId);                              // look for a free copy
        if (copy == null) {                                                 // none free
            holds.get(bookId).add(memberId);                                  // enqueue FIFO
            for (LibraryObserver obs : observers) obs.onHoldPlaced(memberId, bookId); // notify
            return null; // no loan yet, just a hold
        }
        copy.setStatus(CopyStatus.CHECKED_OUT);                             // claim the copy
        loanCounter++;                                                       // bump id counter
        String loanId = "LOAN-" + loanCounter;                               // build id
        int dueDay = eligibilityStrategy.loanDurationDays(book.getCategory()); // duration by category
        Loan loan = new Loan(loanId, memberId, copy.getCopyId(), bookId, 0, dueDay); // build loan (checkoutDay 0 for this demo)
        loans.put(loanId, loan);                                              // store it
        for (LibraryObserver obs : observers) obs.onLoanCreated(loan);       // notify
        return loan; // hand back to caller
    }

    // Returns a copy, computes its fine, and promotes the next held member if any.
    public synchronized double returnBook(String loanId, int returnDay) {
        Loan loan = loans.get(loanId);                                    // look up loan
        if (loan == null) throw new InvalidLoanException("Unknown loan: " + loanId);
        if (!"ACTIVE".equals(loan.getStatus())) throw new LoanNotActiveException("Loan " + loanId + " is not active");
        Book book = books.get(loan.getBookId());                          // look up book for category
        int daysLate = Math.max(0, returnDay-loan.getDueDay());            // days beyond due date
        double fine = eligibilityStrategy.fineForDaysLate(book.getCategory(), daysLate); // capped fine
        Member member = members.get(loan.getMemberId());                   // borrower
        member.addFine(fine);                                                // accrue the fine
        loan.setFine(fine);                                                   // record on the loan
        loan.setStatus("RETURNED");                                           // mark returned
        BookCopy copy = copies.get(loan.getCopyId());                        // the copy this loan held
        copy.setStatus(CopyStatus.AVAILABLE);                                  // free it
        for (LibraryObserver obs : observers) obs.onLoanReturned(loan, fine); // notify
        java.util.List<String> queue = holds.get(loan.getBookId());          // this title's hold queue
        if (!queue.isEmpty()) {                                                // someone is waiting
            String promotedMemberId = queue.remove(0);                          // longest-waiting member
            copy.setStatus(CopyStatus.CHECKED_OUT);                              // claim the freed copy
            loanCounter++;                                                        // bump id counter
            String newLoanId = "LOAN-" + loanCounter;                             // build id
            int newDueDay = returnDay + eligibilityStrategy.loanDurationDays(book.getCategory()); // fresh due date
            Loan promotedLoan = new Loan(newLoanId, promotedMemberId, copy.getCopyId(), loan.getBookId(), returnDay, newDueDay); // build loan
            loans.put(newLoanId, promotedLoan);                                    // store it
            for (LibraryObserver obs : observers) obs.onLoanCreated(promotedLoan); // notify
        }
        return fine; // hand back to caller
    }
}

