using namespace std;

// Observer interface: reacts to library lifecycle events.
class LibraryObserver {
public:
    virtual void onLoanCreated(const Loan& loan) = 0;
    virtual void onLoanRejected(const string& memberId, const string& reason) = 0;
    virtual void onHoldPlaced(const string& memberId, const string& bookId) = 0;
    virtual void onLoanReturned(const Loan& loan, double fine) = 0;
    virtual ~LibraryObserver() {}
};

// Simple observer that prints events to the console.
class ConsoleLibraryObserver : public LibraryObserver {
public:
    void onLoanCreated(const Loan& loan) override {
        cout << "Loan " << loan.loanId << " created for " << loan.memberId << ", copy " << loan.copyId << ", due day " << loan.dueDay << endl;
    }
    void onLoanRejected(const string& memberId, const string& reason) override {
        cout << "Checkout rejected for " << memberId << ": " << reason << endl;
    }
    void onHoldPlaced(const string& memberId, const string& bookId) override {
        cout << "Hold placed for " << memberId << " on book " << bookId << endl;
    }
    void onLoanReturned(const Loan& loan, double fine) override {
        cout << "Loan " << loan.loanId << " returned by " << loan.memberId << ", fine " << fine << endl;
    }
};

// Custom exceptions for the realistic failure modes.
class BorrowingNotEligibleException : public runtime_error {
public: BorrowingNotEligibleException(const string& msg) : runtime_error(msg) {}
};
class InvalidLoanException : public runtime_error {
public: InvalidLoanException(const string& msg) : runtime_error(msg) {}
};
class LoanNotActiveException : public runtime_error {
public: LoanNotActiveException(const string& msg) : runtime_error(msg) {}
};

// The core orchestrator tying every piece together.
class LibraryService {
    map<string, Book> books;                     // bookId -> Book
    map<string, BookCopy> copies;                 // copyId -> BookCopy
    map<string, Member> members;                  // memberId -> Member
    map<string, Loan> loans;                      // loanId -> Loan
    map<string, vector<string>> holds;            // bookId -> FIFO queue of memberIds
    shared_ptr<BorrowingEligibilityStrategy> eligibilityStrategy; // pluggable policy
    vector<shared_ptr<LibraryObserver>> observers; // listeners
    int loanCounter = 0;                             // simple id generator

    int activeLoanCount(string memberId) {
        int count = 0;                                    // running total
        for (auto& entry : loans) {                          // scan all loans
            if (entry.second.memberId == memberId && entry.second.status == "ACTIVE") count++; // count active ones
        }
        return count; // total active loans for this member
    }

    string findFreeCopyId(string bookId) {
        for (auto& entry : copies) {                          // scan all copies
            if (entry.second.bookId == bookId && entry.second.isAvailable()) return entry.first; // first free copy of this title
        }
        return ""; // no free copy
    }

public:
    LibraryService(shared_ptr<BorrowingEligibilityStrategy> strategy) : eligibilityStrategy(strategy) {}

    void addBook(Book book) { books.insert({book.bookId, book}); holds[book.bookId] = {}; } // register a book and its hold queue
    void addCopies(vector<BookCopy> newCopies) { for (auto& c : newCopies) copies.insert({c.copyId, c}); } // register copies
    void addMember(Member member) { members.insert({member.memberId, member}); } // register a member
    void addObserver(shared_ptr<LibraryObserver> observer) { observers.push_back(observer); } // register a listener

    Loan* checkout(string memberId, string bookId) {
        Member& member = members.at(memberId);                  // look up member
        Book& book = books.at(bookId);                            // look up book
        string reason = eligibilityStrategy->checkEligibility(member, activeLoanCount(memberId)); // eligibility check
        if (!reason.empty()) {                                       // not eligible
            for (auto& obs : observers) obs->onLoanRejected(memberId, reason); // notify
            throw BorrowingNotEligibleException(reason);
        }
        string copyId = findFreeCopyId(bookId);                    // look for a free copy
        if (copyId.empty()) {                                         // none free
            holds[bookId].push_back(memberId);                          // enqueue FIFO
            for (auto& obs : observers) obs->onHoldPlaced(memberId, bookId); // notify
            return nullptr; // no loan yet, just a hold
        }
        copies.at(copyId).status = CopyStatus::CHECKED_OUT;           // claim the copy
        loanCounter++;                                                  // bump id counter
        string loanId = "LOAN-" + to_string(loanCounter);               // build id
