        auto& queue = holds[loan.bookId];                                // this title's hold queue
        if (!queue.empty()) {                                              // someone is waiting
            string promotedMemberId = queue.front();                        // longest-waiting member
            queue.erase(queue.begin());                                       // dequeue it
            copy.status = CopyStatus::CHECKED_OUT;                             // claim the freed copy
            loanCounter++;                                                      // bump id counter
            string newLoanId = "LOAN-" + to_string(loanCounter);                 // build id
            int newDueDay = returnDay + eligibilityStrategy->loanDurationDays(book.category); // fresh due date
            loans[newLoanId] = Loan(newLoanId, promotedMemberId, loan.copyId, loan.bookId, returnDay, newDueDay); // build loan
            for (auto& obs : observers) obs->onLoanCreated(loans[newLoanId]); // notify
        }
        return fine; // hand back to caller
    }
