class LoanNotActiveException extends RuntimeException {
    public LoanNotActiveException(String msg) { super(msg); }
}

class LibraryService {
    private final Map<String, Book> books = new HashMap<>();
    private final Map<String, BookCopy> copies = new HashMap<>();
    private final Map<String, Member> members = new HashMap<>();
    private final Map<String, Loan> loans = new HashMap<>();
    private final Map<String, List<String>> holds = new HashMap<>();
    private final BorrowingEligibilityStrategy eligibilityStrategy;
    private final List<LibraryObserver> observers = new ArrayList<>();
    private int loanCounter = 0;

    public LibraryService(BorrowingEligibilityStrategy eligibilityStrategy) {
        this.eligibilityStrategy = eligibilityStrategy;
    }

    public void addBook(Book book) { books.put(book.getBookId(), book); holds.put(book.getBookId(), new ArrayList<>()); }
    public void addCopies(List<BookCopy> newCopies) { for (BookCopy c : newCopies) copies.put(c.getCopyId(), c); }
    public void addMember(Member member) { members.put(member.getMemberId(), member); }
    public void addObserver(LibraryObserver observer) { observers.add(observer); }

    private int activeLoanCount(String memberId) {
        int count = 0;
        for (Loan l : loans.values()) {
            if (l.getMemberId().equals(memberId) && "ACTIVE".equals(l.getStatus())) count++;
        }
        return count;
    }

    private BookCopy findFreeCopy(String bookId) {
        for (BookCopy c : copies.values()) {
            if (c.getBookId().equals(bookId) && c.isAvailable()) return c;
        }
        return null;
    }

    public synchronized Loan checkout(String memberId, String bookId) {
        Member member = members.get(memberId);
        Book book = books.get(bookId);
        String reason = eligibilityStrategy.checkEligibility(member, activeLoanCount(memberId));
        if (reason != null) {
            for (LibraryObserver obs : observers) obs.onLoanRejected(memberId, reason);
            throw new BorrowingNotEligibleException(reason);
        }
        BookCopy copy = findFreeCopy(bookId);
        if (copy == null) {
            holds.get(bookId).add(memberId);
            for (LibraryObserver obs : observers) obs.onHoldPlaced(memberId, bookId);
            return null;
        }
        copy.setStatus(CopyStatus.CHECKED_OUT);
        loanCounter++;
        String loanId = "LOAN-" + loanCounter;
        int dueDay = eligibilityStrategy.loanDurationDays(book.getCategory());
        Loan loan = new Loan(loanId, memberId, copy.getCopyId(), bookId, 0, dueDay);
        loans.put(loanId, loan);
        for (LibraryObserver obs : observers) obs.onLoanCreated(loan);
        return loan;
    }

    public synchronized double returnBook(String loanId, int returnDay) {
        Loan loan = loans.get(loanId);
        if (loan == null) throw new InvalidLoanException("Unknown loan: " + loanId);
        if (!"ACTIVE".equals(loan.getStatus())) throw new LoanNotActiveException("Loan " + loanId + " is not active");
        Book book = books.get(loan.getBookId());
        int daysLate = Math.max(0, returnDay-loan.getDueDay());
        double fine = eligibilityStrategy.fineForDaysLate(book.getCategory(), daysLate);
        Member member = members.get(loan.getMemberId());
        member.addFine(fine);
        loan.setFine(fine);
        loan.setStatus("RETURNED");
        BookCopy copy = copies.get(loan.getCopyId());
        copy.setStatus(CopyStatus.AVAILABLE);
        for (LibraryObserver obs : observers) obs.onLoanReturned(loan, fine);
        List<String> queue = holds.get(loan.getBookId());
        if (!queue.isEmpty()) {
            String promotedMemberId = queue.remove(0);
            copy.setStatus(CopyStatus.CHECKED_OUT);
            loanCounter++;
            String newLoanId = "LOAN-" + loanCounter;
            int newDueDay = returnDay + eligibilityStrategy.loanDurationDays(book.getCategory());
            Loan promotedLoan = new Loan(newLoanId, promotedMemberId, copy.getCopyId(), loan.getBookId(), returnDay, newDueDay);
            loans.put(newLoanId, promotedLoan);
            for (LibraryObserver obs : observers) obs.onLoanCreated(promotedLoan);
        }
        return fine;
    }
}

