};
class LoanNotActiveException : public runtime_error {
public: LoanNotActiveException(const string& msg) : runtime_error(msg) {}
};

class LibraryService {
    map<string, Book> books;
    map<string, BookCopy> copies;
    map<string, Member> members;
    map<string, Loan> loans;
    map<string, vector<string>> holds;
    shared_ptr<BorrowingEligibilityStrategy> eligibilityStrategy;
    vector<shared_ptr<LibraryObserver>> observers;
    int loanCounter = 0;

    int activeLoanCount(string memberId) {
        int count = 0;
        for (auto& entry : loans) {
            if (entry.second.memberId == memberId && entry.second.status == "ACTIVE") count++;
        }
        return count;
    }

    string findFreeCopyId(string bookId) {
        for (auto& entry : copies) {
            if (entry.second.bookId == bookId && entry.second.isAvailable()) return entry.first;
        }
        return "";
    }

public:
    LibraryService(shared_ptr<BorrowingEligibilityStrategy> strategy) : eligibilityStrategy(strategy) {}

    void addBook(Book book) { books.insert({book.bookId, book}); holds[book.bookId] = {}; }
    void addCopies(vector<BookCopy> newCopies) { for (auto& c : newCopies) copies.insert({c.copyId, c}); }
    void addMember(Member member) { members.insert({member.memberId, member}); }
    void addObserver(shared_ptr<LibraryObserver> observer) { observers.push_back(observer); }

    Loan* checkout(string memberId, string bookId) {
        Member& member = members.at(memberId);
        Book& book = books.at(bookId);
        string reason = eligibilityStrategy->checkEligibility(member, activeLoanCount(memberId));
        if (!reason.empty()) {
            for (auto& obs : observers) obs->onLoanRejected(memberId, reason);
            throw BorrowingNotEligibleException(reason);
        }
        string copyId = findFreeCopyId(bookId);
        if (copyId.empty()) {
            holds[bookId].push_back(memberId);
            for (auto& obs : observers) obs->onHoldPlaced(memberId, bookId);
            return nullptr;
        }
        copies.at(copyId).status = CopyStatus::CHECKED_OUT;
        loanCounter++;
        string loanId = "LOAN-" + to_string(loanCounter);
        int dueDay = eligibilityStrategy->loanDurationDays(book.category);
        loans[loanId] = Loan(loanId, memberId, copyId, bookId, 0, dueDay);
        for (auto& obs : observers) obs->onLoanCreated(loans[loanId]);
        return &loans[loanId];
    }

    double returnBook(string loanId, int returnDay) {
        auto it = loans.find(loanId);
        if (it == loans.end()) throw InvalidLoanException("Unknown loan: " + loanId);
        Loan& loan = it->second;
        if (loan.status != "ACTIVE") throw LoanNotActiveException("Loan " + loanId + " is not active");
        Book& book = books.at(loan.bookId);
        int daysLate = max(0, returnDay-loan.dueDay);
        double fine = eligibilityStrategy->fineForDaysLate(book.category, daysLate);
        Member& member = members.at(loan.memberId);
        member.addFine(fine);
        loan.fine = fine;
        loan.status = "RETURNED";
        BookCopy& copy = copies.at(loan.copyId);
        copy.status = CopyStatus::AVAILABLE;
        for (auto& obs : observers) obs->onLoanReturned(loan, fine);
        auto& queue = holds[loan.bookId];
        if (!queue.empty()) {
            string promotedMemberId = queue.front();
            queue.erase(queue.begin());
            copy.status = CopyStatus::CHECKED_OUT;
            loanCounter++;
            string newLoanId = "LOAN-" + to_string(loanCounter);
            int newDueDay = returnDay + eligibilityStrategy->loanDurationDays(book.category);
            loans[newLoanId] = Loan(newLoanId, promotedMemberId, loan.copyId, loan.bookId, returnDay, newDueDay);
            for (auto& obs : observers) obs->onLoanCreated(loans[newLoanId]);
        }
        return fine;
    }
};

int main() {
    auto service = LibraryService(make_shared<LimitAndFineEligibilityStrategy>());
    service.addObserver(make_shared<ConsoleLibraryObserver>());

    Book b1("B1", "Design Patterns", BookCategory::PREMIUM);
    Book b2("B2", "Intro to Algorithms", BookCategory::REGULAR);
    service.addBook(b1);
    service.addBook(b2);

    BookCopyFactory factory;
    service.addCopies(factory.createCopies("B1", 1));
    service.addCopies(factory.createCopies("B2", 1));

    service.addMember(Member("Alice", "Alice", 0.0));
    service.addMember(Member("Bob", "Bob", 0.0));
    service.addMember(Member("Carol", "Carol", 6.0));

    Loan* loan1 = service.checkout("Alice", "B1");

    service.checkout("Bob", "B1");

    try {
        service.checkout("Carol", "B2");
    } catch (BorrowingNotEligibleException& e) {
        cout << "Caught expected: " << e.what() << endl;
    }

    service.returnBook(loan1->loanId, 10);

    return 0;
}
